        int node = curr[0];
        int time = curr[1];
        if (dist[node] != -1 && dist[node] <= time) {
            continue;
        }
        dist[node] = time;
        if (hasApple[node]) {
            return time;
        }
        for (int[] edge : edges) {
            int neighbor = edge[0] == node ? edge[1] : edge[0];
            if (dist[neighbor] == -1) {
                pq.offer(new int[]{neighbor, time + 1});
            }
        }
    }
    return -1;
}
