public String sortString(String s) {
    // Step 1: Sort the characters of s in ascending order
    char[] sortedChars = s.toCharArray();
    Arrays.sort(sortedChars);

    // Step 2: Sort the characters of s in descending order
    char[] sortedCharsReverse = new char[sortedChars.length];
    for (int i = sortedChars.length - 1; i >= 0; i--) {
        sortedCharsReverse[sortedChars.length - 1 - i] = sortedChars[i];
    }

    // Step 3: Combine the sorted characters in alternating order
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < sortedChars.length; i++) {
        result.append(sortedChars[i]);
        result.append(sortedCharsReverse[i]);
    }

    return result.toString();
}

