public boolean hasAllCodes(String s, int k) {
    if (s == null || s.isEmpty() || k < 1) {
        throw new IllegalArgumentException("Input string and k must be non-null and positive");
    }

    int n = s.length();
    int[] count = new int[2];
    for (int i = 0; i < n; i++) {
        if (s.charAt(i) == '0') {
            count[0]++;
        } else {
            count[1]++;
        }
    }

    if (count[0] < k || count[1] < k) {
        return false;
    }

    for (int i = 0; i < n - k + 1; i++) {
        if (count[s.charAt(i) == '0' ? 0 : 1] < k) {
            return false;
        }
    }

    return true;
}

