public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOps = 0;
    while (arr[0] != arr[n - 1]) {
        int minDiff = getMinDiff(arr);
        int x = getIndexWithMinDiff(arr, minDiff);
        int y = getIndexWithMaxDiff(arr, minDiff);
        arr[x] -= 1;
        arr[y] += 1;
        minOps++;
    }

    return minOps;
}

private int getMinDiff(int[] arr) {
    int minDiff = Integer.MAX_VALUE;
    for (int i = 0; i < arr.length - 1; i++) {
        int diff = Math.abs(arr[i] - arr[i + 1]);
        if (diff < minDiff) {
            minDiff = diff;
        }
    }
    return minDiff;
}

private int getIndexWithMinDiff(int[] arr, int minDiff) {
    for (int i = 0; i < arr.length - 1; i++) {
        if (Math.abs(arr[i] - arr[i + 1]) == minDiff) {
            return i;
        }
    }
    return -1;
