private int getIndexWithMaxDiff(int[] arr, int minDiff) {
    int maxDiff = Integer.MIN_VALUE;
    int index = -1;
    for (int i = 0; i < arr.length - 1; i++) {
        int diff = Math.abs(arr[i] - arr[i + 1]) - minDiff;
        if (diff > maxDiff) {
            maxDiff = diff;
            index = i;
        }
    }
    return index;
}

