/**
* @param n the length of the string
* @param k the value of the string
* @return the lexicographically smallest string of length n and value k
*/
public static String getSmallestString(int n, int k) {
    // Initialize an empty string builder with the correct length
    StringBuilder sb = new StringBuilder(n);

    // Create a map of character positions in the alphabet
    Map<Character, Integer> charPositions = new HashMap<>();
    for (int i = 1; i <= 26; i++) {
        charPositions.put((char)('a' + i - 1), i);
    }

    // Add characters to the string builder until the value of the string is equal to k
    while (sb.length() < n && sb.toString().chars().sum() < k) {
        // Get the next character that contributes the least to the string value
        char nextChar = getNextChar(charPositions, sb.toString().chars().sum());

        // Add the character to the string builder
        sb.append(nextChar);
    }

    // Return the lexicographically smallest string
    return sb.toString();
}

/**
* @param charPositions a map of character positions in the alphabet
* @param totalValue the total value of the string
* @return the next character that contributes the least to the string value
*/
private static char getNextChar(Map<Character, Integer> charPositions, int totalValue) {
    // Find the character with the smallest position value that is not already used
    char nextChar = 'a';
    int nextValue = Integer.MAX_VALUE;
    for (Map.Entry<Character, Integer> entry : charPositions.entrySet()) {
        char c = entry.getKey();
        int v = entry.getValue();
        if (v < nextValue && !sb.toString().contains(c)) {
            nextChar = c;
            nextValue = v;
        }
    }

    // Update the character positions map
    charPositions.put(nextChar, nextValue);

    // Return the next character
    return nextChar;
}

